INSERT INTO kv_store (key, value) VALUES ('sheets_config', '{"spreadsheetId":"1C4_1Ja7oWGuPAlYIRy0BqS812xEQZRlCwQuW-uKzsu4","webAppUrl":"","lastSynced":"","articles":[{"title":"Cẩm nang quy trình đăng ký giấy phép và công bố mỹ phẩm mới nhất 2026","category":"cẩm nang","summary":"Hướng dẫn chi tiết từ A-Z các hồ sơ pháp lý, thủ tục kiểm nghiệm lâm sàng và các bước nộp hồ sơ công bố mỹ phẩm thành công lên Bộ Y Tế.","content":"Để một sản phẩm mỹ phẩm được phép lưu thông hợp pháp trên thị trường Việt Nam, doanh nghiệp cần thực hiện đầy đủ các bước kiểm nghiệm chất lượng và công bố sản phẩm tại Cục Quản lý Dược hoặc Sở Y Tế. Các hồ sơ thiết yếu bao gồm: phiếu kiểm nghiệm chất lượng sản phẩm từ phòng Lab được cấp phép, bản phân tích thành phần phần trăm nguyên liệu (INCI name), giấy chứng nhận đăng ký kinh doanh có ngành nghề phù hợp, và hồ sơ thông tin sản phẩm (PIF). Tại Cosbuilt, chúng tôi hỗ trợ khách hàng toàn bộ hồ sơ này một cách nhanh chóng và an tâm nhất.","image":"https://images.unsplash.com/photo-1450133064473-71024230f91b?q=80&w=600","author":"ThS. Luật sư Nguyễn Khánh Ly","date":"12 Tháng 6, 2026"},{"title":"Xu hướng hoạt chất mỹ phẩm lên ngôi nửa cuối năm 2026: Exosome & Bakuchiol","category":"xu hướng","summary":"Khám phá sự trỗi dậy mạnh mẽ của công nghệ sinh học Exosome và hoạt chất thay thế retinol dịu nhẹ Bakuchiol trong các sản phẩm chăm sóc da cao cấp.","content":"Năm 2026 chứng kiến bước chuyển mình mạnh mẽ từ các hoạt chất hóa học truyền thống sang công nghệ sinh học tế bào. Điển hình là Exosome - chất truyền tin tế bào siêu nhỏ có khả năng kích hoạt tái tạo collagen tự thân gấp 300% so với tế bào gốc thông thường. Đồng thời, Bakuchiol tiếp tục khẳng định vị thế là ngôi sao sáng cho làn da nhạy cảm nhờ hiệu quả chống lão hóa tương đương Retinol nhưng không gây bong tróc, mẩn đỏ. Việc ứng dụng sớm các hoạt chất này giúp thương hiệu tạo ra USP mạnh mẽ.","image":"https://images.unsplash.com/photo-1512290923902-8a9f81dc236c?q=80&w=600","author":"TS. Lê Hoài Nam (Trưởng phòng R&D Cosbuilt)","date":"05 Tháng 07, 2026"},{"title":"Kinh nghiệm tối ưu hóa chi phí sản xuất ban đầu cho startup mỹ phẩm","category":"cẩm nang","summary":"Làm thế nào để khởi nghiệp mỹ phẩm với số vốn tối thiểu nhưng vẫn đảm bảo chất lượng mẫu mã bắt mắt và sản phẩm đạt chuẩn CGMP?","content":"Nhiều chủ thương hiệu mới bắt đầu thường mắc sai lầm khi đặt hàng số lượng quá lớn (MOQ cao) gây đọng vốn, hoặc chọn chai lọ quá đắt tiền. Lời khuyên từ chuyên gia của Cosbuilt là: 1. Hãy bắt đầu với danh mục tối giản 1-2 SKU cốt lõi. 2. Ưu tiên lựa chọn hũ/chai tiêu chuẩn có sẵn và tạo điểm nhấn bằng thiết kế nhãn dán, vỏ hộp ép kim tinh tế. 3. Tận dụng tối đa chính sách hỗ trợ MOQ thấp từ nhà máy trực tiếp như Cosbuilt để thử nghiệm phản ứng thị trường trước khi sản xuất quy mô lớn.","image":"https://images.unsplash.com/photo-1434626881859-194d67b2b86f?q=80&w=600","author":"Bà Trần Minh Tâm (Giám đốc Dự án Cosbuilt)","date":"28 Tháng 5, 2026"},{"title":"Thảo mộc Việt lên ngôi: Tiềm năng khổng lồ từ mỹ phẩm hữu cơ thuần chay","category":"xu hướng","summary":"Người tiêu dùng ngày càng thông thái và ưu ái các sản phẩm chứa nguồn nguyên liệu bản địa như hoa bưởi, trà xanh, tía tô, rau má.","content":"Mỹ phẩm thiên nhiên không còn là khái niệm xa lạ, nhưng sự nâng cấp lên chuẩn Thuần chay (Vegan) và sử dụng thảo dược bản địa Việt Nam đang tạo nên cơn sốt. Khách hàng cực kỳ ưa chuộng các câu chuyện thương hiệu gắn liền với bảo tồn thiên nhiên và nông nghiệp bền vững. Rau má làm dịu, tía tô trị thâm nám, vỏ bưởi mọc tóc đang là những đề tài R&D cực kỳ hot tại phòng Lab của Cosbuilt. Chúng tôi giúp trích ly hoạt chất nồng độ cao giữ trọn đặc tính dược lý tốt nhất của nguyên liệu nội địa.","image":"https://images.unsplash.com/photo-1608571423902-eed4a5ad8108?q=80&w=600","author":"KS. Nguyễn Thị Mai (Phó Phòng R&D)","date":"19 Tháng 6, 2026"}],"images":[{"title":"Dây chuyền chiết rót mỹ phẩm tự động","category":"nhà máy","description":"Hệ thống chiết rót công nghệ tự động hóa khép kín nhập khẩu từ Đức và Hàn Quốc, chuẩn CGMP ASEAN.","image":"https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?q=80&w=600"},{"title":"Phòng thí nghiệm nghiên cứu R&D vô trùng","category":"R&D","description":"Nơi đội ngũ tiến sĩ, thạc sĩ sinh hóa nghiên cứu, phát triển và thử nghiệm các công thức mỹ phẩm đột phá.","image":"https://images.unsplash.com/photo-1576086213369-97a306d36557?q=80&w=600"},{"title":"Hệ thống bồn nhũ hóa hút chân không đồng hóa","category":"nhà máy","description":"Bồn khuấy trộn nhũ hóa siêu mịn giúp chất kem đạt độ đồng đều tối đa và giữ trạng thái ổn định lâu dài.","image":"https://images.unsplash.com/photo-1608248597279-f99d160bfcbc?q=80&w=600"},{"title":"Thử nghiệm lâm sàng và kiểm tra kích ứng da","category":"R&D","description":"Các công thức mẫu thử được kiểm nghiệm lâm sàng nghiêm ngặt nhằm đảm bảo an toàn tuyệt đối trước khi công bố.","image":"https://images.unsplash.com/photo-1527799822341-478a783b83d0?q=80&w=600"},{"title":"Kho nguyên liệu thô nhập khẩu đạt chuẩn","category":"nhà máy","description":"Nguồn nguyên liệu thô nhập khẩu chính ngạch trực tiếp từ Nhật Bản, Thụy Sĩ, Pháp, lưu giữ trong điều kiện tối ưu.","image":"https://images.unsplash.com/photo-1586495777744-4413f21062fa?q=80&w=600"},{"title":"Quy trình đóng gói màng co vô trùng hoàn thiện","category":"đóng gói","description":"Sản phẩm được làm sạch bụi lọ, đóng màng co vô trùng và in hạn sử dụng tự động trước khi xuất xưởng.","image":"https://images.unsplash.com/photo-1556229174-5e42a09e45af?q=80&w=600"}]}')
ON CONFLICT(key) DO UPDATE SET value = excluded.value;
